package com.anibiar.app.ui.inbox

import androidx.compose.ui.Alignment
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import com.anibiar.app.R

/** Where the decoration sits on the bubble. */
enum class DecoSpot { TopEnd, TopStart, TopCenter }

/**
 * One chat bubble look. Kiro's own set: a flat colour (or gentle gradient) plus a small hand-drawn decoration
 * (generated by tools/make_assets.py) sitting on the bubble's edge.
 */
data class BubbleStyle(
    val id: String,
    val name: String,
    val from: Color,
    val to: Color,
    val text: Color,
    val deco: Int? = null,
    val spot: DecoSpot = DecoSpot.TopEnd,
    val decoWidth: Int = 34,
    val decoHeight: Int = 34,
) {
    val brush: Brush get() = Brush.linearGradient(listOf(from, to))
    val alignment: Alignment get() = when (spot) { DecoSpot.TopEnd -> Alignment.TopEnd; DecoSpot.TopStart -> Alignment.TopStart; DecoSpot.TopCenter -> Alignment.TopCenter }
}

object BubbleStyles {
    private val ink = Color(0xFF1C1C20)
    val all: List<BubbleStyle> = listOf(
        BubbleStyle("default", "Default", Color(0xFF3D7BFF), Color(0xFF2B58F0), Color.White),
        BubbleStyle("sakura", "Sakura", Color(0xFFFFD3E4), Color(0xFFFFC2DA), ink, R.drawable.bub_sakura, DecoSpot.TopEnd, 34, 34),
        BubbleStyle("frog", "Frog eyes", Color(0xFF22B573), Color(0xFF16A064), Color.White, R.drawable.bub_frog, DecoSpot.TopStart, 52, 30),
        BubbleStyle("cat", "Peek cat", Color(0xFFFFF0D2), Color(0xFFFFE8B8), ink, R.drawable.bub_cat, DecoSpot.TopStart, 52, 28),
        BubbleStyle("duck", "Rubber duck", Color(0xFFFFEA85), Color(0xFFFFE15C), ink, R.drawable.bub_duck, DecoSpot.TopEnd, 38, 38),
        BubbleStyle("night", "Starry night", Color(0xFF2A2F6E), Color(0xFF1B1F52), Color.White, R.drawable.bub_stars, DecoSpot.TopEnd, 52, 26),
        BubbleStyle("bubbly", "Bubbly", Color(0xFF8BDDF5), Color(0xFF63CBEC), ink, R.drawable.bub_bubbles, DecoSpot.TopStart, 52, 32),
        BubbleStyle("heart", "Hearts", Color(0xFFF0496B), Color(0xFFD92F57), Color.White, R.drawable.bub_hearts, DecoSpot.TopEnd, 50, 28),
        BubbleStyle("cloud", "Cloud", Color(0xFFEAF1FF), Color(0xFFDCE8FF), ink, R.drawable.bub_cloud, DecoSpot.TopCenter, 54, 28),
        BubbleStyle("mono", "Mono", Color(0xFF3A3A3F), Color(0xFF2E2E33), Color.White),
    )
    fun of(id: String?): BubbleStyle = all.firstOrNull { it.id == id } ?: all.first()
}

